export class TestView {
  values = [];

  constructor(start, count) {
    for (let i = start; i < start + count; i++) {
      this.values.push(i);
    }
  }

  get rowCount() {
    return this.values.length;
  }

  getCellText(index, columnID) {
    return `${columnID} ${this.values[index]}`;
  }

  isContainer() {
    return false;
  }

  isContainerOpen() {
    return false;
  }

  getLevel(_index) {
    return 0;
  }

  selectionChanged() {}

  setTree() {}
}
